 "aspnet-di-corrigir-captura":{"accepted":["escopo"],"solution":"using Microsoft.Extensions.DependencyInjection;\n\nvar servicos = new ServiceCollection();\nservicos.AddScoped<EstadoPedido>();\nservicos.AddScoped<ResumoPedido>();\nusing var provedor = servicos.BuildServiceProvider(\n    new ServiceProviderOptions { ValidateScopes = true, ValidateOnBuild = true });\nforeach (int quantidade in new[] { 2, 1 }) {\n    using var escopo = provedor.CreateScope();\n    var resumo = escopo.ServiceProvider.GetRequiredService<ResumoPedido>();\n    for (int indice = 0; indice < quantidade; indice++)\n        Console.WriteLine(resumo.Contar());\n}\nsealed class EstadoPedido {\n    public int Itens { get; set; }\n}\nsealed class ResumoPedido(EstadoPedido estado) {\n    public int Contar() => ++estado.Itens;\n}","failure":"O resumo conserva o estado que recebeu na construção. Silenciar a validação ou mudar apenas o registro desse estado não garante isolamento por pedido; um singleton continua guardando seu colaborador."},
 "aspnet-di-montar-escopo":{"accepted":[],"order":["colecao","recurso","relatorio","provedor","escopo","resolver","usar","fechar"],"solution":"using Microsoft.Extensions.DependencyInjection;\n\nvar servicos = new ServiceCollection();\nservicos.AddScoped<RecursoPedido>();\nservicos.AddScoped<RelatorioPedido>();\nusing var provedor = servicos.BuildServiceProvider(new ServiceProviderOptions { ValidateScopes = true, ValidateOnBuild = true });\nusing (var escopo = provedor.CreateScope()) {\n    var relatorio = escopo.ServiceProvider.GetRequiredService<RelatorioPedido>();\n    Console.WriteLine(relatorio.Ler());\n}\nsealed class RecursoPedido : IDisposable {\n    private bool descartado;\n    public int Ler() {\n        ObjectDisposedException.ThrowIf(descartado, this);\n        return 7;\n    }\n    public void Dispose() {\n        if (descartado) return;\n        descartado = true;\n        Console.WriteLine(\"liberado\");\n    }\n}\nsealed class RelatorioPedido(RecursoPedido recurso) {\n    public int Ler() => recurso.Ler();\n}","failure":"Confira quais registros já existiam quando o provedor foi construído, de onde o relatório é resolvido e quando o escopo fecha. Uma referência disponível na memória não prolonga o prazo de uso de um recurso descartado."},
