 "js-fetch-prever-cancelamento":{"accepted":["AbortError\ntrue\n1"],"failure":"O sinal já foi abortado quando Fetch o recebe. Sem motivo personalizado, a rejeição é AbortError; aborted continua true e repetir abort não dispara um segundo evento.","solution":"AbortError\ntrue\n1"},
 "js-fetch-finalizar-atual":{"accepted":["atual"],"failure":"O finally antigo não deve desligar uma busca mais recente. O teste de identidade também precisa encerrar a busca atual em sucesso ou rejeição, mesmo quando não houve sobreposição.","solution":"let pedidoAtual = 0;\nlet carregando = false;\nasync function buscar(espera) {\n  const pedido = ++pedidoAtual;\n  carregando = true;\n  try {\n    await espera;\n  } finally {\n      if (pedido === pedidoAtual) carregando = false;\n  }\n}\nasync function demonstrar() {\n  let liberarAntiga;\n  let liberarAtual;\n  const primeira = buscar(new Promise(concluir => { liberarAntiga = concluir; }));\n  const segunda = buscar(new Promise(concluir => { liberarAtual = concluir; }));\n  liberarAntiga();\n  await primeira;\n  console.log(carregando);\n  liberarAtual();\n  await segunda;\n  console.log(carregando);\n}\ndemonstrar();"},
